  contenu constant jsonb := '{"status":"PREPARE_NON_PUBLIE_RELAIS_CHATGPT","issue":122,"baseline_main":"d5710fb36b4ef11a7ddc52c04c3ee0113aa9750e","baseline_events":2307,"events":[{"proposal_id":"M2-001","id":"EVT-2800","group":"sport","title":"Lewis Hamilton remporte sa première course de Formule 1 au Canada","start_year":2007,"start_month":6,"start_day":10,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0105","COL-0110","COL-0062"],"description":"Dès sa première saison chez McLaren, Hamilton gagne à Montréal. Cette victoire ouvre le palmarès de l’un des grands champions de la discipline.","sources":[{"url":"https://www.formula1.com/en/latest/article/the-first-win-david-tremayne-remembers-the-magical-day-in-montreal-when.7LcPipB3rPKUuGSqNVYF1U","evidence":"Première victoire à Montréal le 10 juin 2007 ; la mention erronée du samedi dans l’article n’est pas reprise.","checked_on":"2026-10-17"}],"level_reason":"Champion mondialement connu et début de son palmarès.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-002","id":"EVT-2801","group":"sport","title":"Michael Schumacher gagne son premier Grand Prix à Spa","start_year":1992,"start_month":8,"start_day":30,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0105","COL-0110","COL-0062","COL-0082"],"description":"Le pilote allemand gagne en Belgique au volant d’une Benetton. La course disputée sur le circuit de Spa marque une étape majeure de son ascension.","sources":[{"url":"https://www.formula1.com/en/results/1992/races/585/belgium/race-result","evidence":"Belgian Grand Prix, 30 Aug 1992 : Schumacher premier.","checked_on":"2026-10-17"},{"url":"https://www.formula1.com/en/latest/article/the-top-10-f1-drivers-with-the-longest-gap-between-their-first-and-last-wins.5EXRiYajNaTqFS5NzBtCXc","evidence":"F1 confirme que la première victoire de Schumacher est obtenue en Belgique en 1992.","checked_on":"2026-10-17"}],"level_reason":"Premier succès d’un champion très con