roposal_id":"M2-088","id":"EVT-2887","group":"fun","title":"Apple présente sa tablette iPad","start_year":2010,"start_month":1,"start_day":27,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0113","COL-0115"],"description":"Apple dévoile une tablette à écran tactile destinée à la lecture, au web et aux applications. L’annonce précède la commercialisation du produit.","sources":[{"url":"https://www.apple.com/hk/en/newsroom/2010/01/27Apple-Launches-iPad/","evidence":"Communiqué original du 27 janvier 2010 : présentation de l’iPad.","checked_on":"2026-10-17"}],"level_reason":"Objet numérique très connu, annonce clairement distinguée de la vente.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-089","id":"EVT-2888","group":"fun","title":"iRobot lance l’aspirateur robot Roomba aux États-Unis","start_year":2002,"start_month":9,"start_day":18,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0113"],"description":"Le robot se déplace dans la maison pour aspirer le sol. Ce produit contribue à diffuser la robotique domestique auprès du grand public.","sources":[{"url":"https://media.irobot.com/2002-09-18-iRobot-Introduces-Roomba-Intelligent-FloorVac-The-First-Automatic-Floor-Cleaner-In-The-U-S","evidence":"Communiqué original : introduction sur le marché américain le 18 septembre 2002.","checked_on":"2026-10-17"}],"level_reason":"Robot ménager reconnaissable, sans prétendre à la première mondiale de tout aspirateur robot.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-090","id":"EVT-2889","group":"fun","title":"Chester Carlson réalise la première image xérographique","start_year":1938,"start_month":10,"start_day":22,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0113","COL-0071","COL-0112","COL-0082"],"description":"Carlson obtient à Astoria une copie à sec portant le nom du lieu et la date. Le procédé électrostatique deviendra la base de nombreuses photocopieuses.","sources":[{"url":"https://news.xerox.co.uk/news/GBR_Xerography_100","evidence":"Xerox : première image xérographique le 22 octobre 1938.","checked_on":"2026-10-17"}],"level_reason":"Technique familière mais inventeur et procédé moins connus.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-091","id":"EVT-2890","group":"fun","title":"Levi Strauss et Jacob Davis obtiennent le brevet du pantalon à rivets","start_year":1873,"start_month":5,"start_day":20,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0113","COL-0081"],"description":"Les rivets renforcent les points fragiles des pantalons de travail. Ce brevet marque une étape fondatrice du jean moderne, sans être l’invention du tissu denim.","sources":[{"url":"https://www.levistrauss.com/2016/05/19/happy-143rd-blue-jeans/","evidence":"Détenteur du brevet : brevet accordé à Strauss et Davis le 20 mai 1873.","checked_on":"2026-10-17"}],"level_reason":"Vêtement universel et détail technique facile à comprendre.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-092","id":"EVT-2891","group":"fun","title":"Le premier SMS transmet le message Merry Christmas","start_year":1992,"start_month":12,"start_day":3,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0113","COL-0112","COL-0062","COL-0082"],"description":"Neil Papworth envoie le message depuis un ordinateur vers un téléphone du réseau Vodafone. Le destinataire ne peut pas répondre par SMS avec cet appareil.","sources":[{"url":"https://www.vodafone.com/news/newsroom/technology/25-anniversary-text-message","evidence":"Vodafone : premier SMS envoyé le 3 décembre 1992.","checked_on":"2026-10-17"}],"level_reason":"Première d’un usage quotidien largement connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-093","id":"EVT-2892","group":"fun","title":"Un paquet de chewing-gum inaugure le passage en caisse par code-barres","start_year":1974,"start_month":6,"start_day":26,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0113","COL-0112","COL-0082"],"description":"Dans un supermarché de l’Ohio, une caissière scanne un paquet de chewing-gum Wrigley. C’est le premier passage commercial en caisse avec le code UPC.","sources":[{"url":"https://support.gs1.org/support/solutions/articles/43000734073-gs1-historical-timeline","evidence":"GS1 : premier produit scanné au supermarché Marsh le 26 juin 1974.","checked_on":"2026-10-17"}],"level_reason":"Objet courant, premier usage précis et anecdote accessible.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-094","id":"EVT-2893","group":"fun","title":"Une erreur d’enveloppe fait annoncer La La Land à la place de Moonlight aux Oscars","start_year":2017,"start_month":2,"start_day":26,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0117","COL-0115"],"description":"Les présentateurs lisent une mauvaise enveloppe pour le prix du meilleur film. L’erreur est corrigée sur scène et Moonlight reçoit finalement la récompense.","sources":[{"url":"https://www.oscars.org/news/statement-pricewaterhousecoopers","evidence":"Déclaration de l’organisateur : mauvaise enveloppe, annonce corrigée ; programme officiel : cérémonie du 26 février 2017 à Los Angeles.","checked_on":"2026-10-17"},{"url":"https://www.oscars.org/oscars/ceremonies/2017","evidence":"Date locale de la cérémonie : dimanche 26 février 2017.","checked_on":"2026-10-17"}],"level_reason":"Erreur télévisée célèbre, distincte de la simple tenue de la cérémonie.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-095","id":"EVT-2894","group":"fun","title":"Le premier vol d’Ariane 5 échoue après une erreur du système de guidage","start_year":1996,"start_month":6,"start_day":4,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0117","COL-0070","COL-0071","COL-0061","COL-0062","COL-0082"],"description":"La fusée décolle de Kourou mais se désintègre peu après. L’enquête met en évidence une défaillance logicielle dans le traitement des informations de navigation.","sources":[{"url":"https://www.esa.int/Newsroom/Press_Releases/Ariane_501_-_Presentation_of_Inquiry_Board_report","evidence":"ESA : premier vol d’Ariane 5 en échec le 4 juin 1996 ; conclusions de l’enquête.","checked_on":"2026-10-17"}],"level_reason":"Échec célèbre de l’histoire spatiale européenne, sans victime humaine à bord.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-096","id":"EVT-2895","group":"fun","title":"La BBC diffuse un faux documentaire montrant des manchots volants","start_year":2008,"start_month":4,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0117","COL-0115","COL-0062"],"description":"Une séquence truquée accompagne un poisson d’avril de la BBC. Les oiseaux y quittent l’Antarctique en volant, un comportement impossible pour de vrais manchots.","sources":[{"url":"https://factcheck.afp.com/flying-penguins-animation-actually-spoof-produced-bbc-april-fools-day-2008","evidence":"Vérification AFP renvoyant à la vidéo originale BBC publiée le 1er avril 2008.","checked_on":"2026-10-17"}],"level_reason":"Canular visuel compréhensible, explicitement présenté comme faux.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-097","id":"EVT-2896","group":"fun","title":"La Suède bascule de la conduite à gauche à la conduite à droite","start_year":1967,"start_month":9,"start_day":3,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0117","COL-0062","COL-0082"],"description":"Le jour H, la circulation est interrompue avant la réorganisation des véhicules sur l’autre côté des routes. Cette opération nationale exige une importante préparation.","sources":[{"url":"https://www.statensmuseermtf.se/vara-museer-och-samlingar/vara-samlingar/transporthistoria/vaghistoriska-samlingarna/trafikhistoria/hogertrafik","evidence":"Musées nationaux suédois des transports : changement dans la nuit du 3 septembre 1967.","checked_on":"2026-10-17"}],"level_reason":"Décision insolite aux conséquences concrètes faciles à imaginer.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-098","id":"EVT-2897","group":"fun","title":"Taco Bell prétend avoir acheté la Liberty Bell dans un poisson d’avril","start_year":1996,"start_month":4,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0117","COL-0082"],"description":"Une publicité annonce faussement l’achat et le changement de nom de la célèbre cloche américaine. L’enseigne révèle le jour même qu’il s’agit d’un canular.","sources":[{"url":"https://www.upi.com/Archives/1996/04/01/Taco-Bell-stages-April-Fools-hoax/8400828334800/","evidence":"Dépêche UPI originale du 1er avril 1996 rapportant le canular et son démenti.","checked_on":"2026-10-17"}],"level_reason":"Canular culturel américain demandant de connaître le monument.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-099","id":"EVT-2898","group":"fun","title":"La fraude de l’homme de Piltdown est révélée","start_year":1953,"start_month":11,"start_day":null,"precision":"MONTH","date_status":"EXACT","niveau":2,"packs":["COL-0117","COL-0071","COL-0062","COL-0082"],"description":"Des analyses démontrent que le prétendu fossile combine des restes humains et une mâchoire d’orang-outan. Le dévoilement de la fraude est distinct de sa présentation initiale en 1912.","sources":[{"url":"https://www.nhm.ac.uk/CalmView/Record.aspx?id=DF%2FPAL%2F116%2F37%2F1&src=CalmView.Catalog","evidence":"Archives du musée : télégramme du 21 novembre 1953 confirmant la fraude ; correspondance voisine du 20 au 24 novembre. Mois retenu sans imposer un unique jour de révélation publique.","checked_on":"2026-10-17"}],"level_reason":"Canular scientifique historique nécessitant un repère spécialisé.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-100","id":"EVT-2899","group":"fun","title":"Alan Sokal révèle son canular publié dans la revue Social Text","start_year":1996,"start_month":null,"start_day":null,"precision":"YEAR","date_status":"EXACT","niveau":3,"packs":["COL-0117","COL-0071","COL-0082"],"description":"Le physicien explique avoir fait publier un texte volontairement absurde. L’affaire déclenche un débat sur la rigueur éditoriale et les rapports entre sciences et études culturelles.","sources":[{"url":"https://physics.nyu.edu/faculty/sokal/lingua_franca_v4/lingua_franca_v4.html","evidence":"Texte original de révélation dans Lingua Franca, numéro mai-juin 1996 ; seule l’année est retenue pour ce numéro double.","checked_on":"2026-10-17"}],"level_reason":"Affaire universitaire spécialisée, niveau expert ; aucune conclusion générale abusivement tirée du canular.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-101","id":"EVT-2900","group":"fun","title":"Sortie de Dangal (Inde)","start_year":2016,"start_month":12,"start_day":23,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0114"],"description":"Le film indien de Nitesh Tiwari, avec Aamir Khan, s’inspire d’un père qui entraîne ses filles à la lutte. Il associe récit familial et émancipation par le sport.","sources":[{"url":"https://akpfilms.com/films/dangal/","evidence":"Producteur Aamir Khan Productions : 23 December 2016 ; The Numbers précise sortie large en Inde à cette date.","checked_on":"2026-10-17"},{"url":"https://www.the-numbers.com/movie/Dangal-%282016-India%29","evidence":"Sortie large Inde le 23 décembre 2016, distincte de la sortie limitée nord-américaine du 21.","checked_on":"2026-10-17"}],"level_reason":"Grand succès du cinéma indien, repère moins familier au public français.","aliases":[],"territory":"Inde","kind":"cinema"},{"proposal_id":"M2-102","id":"EVT-2901","group":"fun","title":"Sortie de La Cité de Dieu (France)","start_year":2003,"start_month":3,"start_day":12,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0114","COL-0061"],"description":"Fernando Meirelles et Kátia Lund mettent en scène la violence et les trajectoires de jeunes d’une favela de Rio. La date concerne la sortie française, après la sortie brésilienne.","sources":[{"url":"https://www.allocine.fr/article/fichearticle_gen_carticle%3D18351100.html","evidence":"Entretien original avec Meirelles, publié le 12 mars 2003 à l’occasion de la sortie en salles ce même jour.","checked_on":"2026-10-17"}],"level_reason":"Film brésilien marquant, territoire français explicitement distingué.","aliases":[],"territory":"France","kind":"cinema"},{"proposal_id":"M2-103","id":"EVT-2902","group":"fun","title":"Sortie de Le Labyrinthe de Pan (France)","start_year":2006,"start_month":11,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0114","COL-0061","COL-0062"],"description":"Guillermo del Toro mêle conte fantastique et violence de l’Espagne franquiste à travers le regard d’une enfant. La date retenue est celle des salles françaises.","sources":[{"url":"https://cineligue-hdf.org/films/le-labyrinthe-de-pan/","evidence":"Cinéligue Hauts-de-France : date de sortie française 1 novembre 2006.","checked_on":"2026-10-17"}],"level_reason":"Film marquant du cinéma hispanophone, niveau intermédiaire.","aliases":[],"territory":"France","kind":"cinema"},{"proposal_id":"M2-104","id":"EVT-2903","group":"fun","title":"William et Catherine Middleton se marient à Westminster","start_year":2011,"start_month":4,"start_day":29,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0116","COL-0062"],"description":"Le mariage du prince britannique et de Catherine Middleton est célébré à l’abbaye de Westminster. La cérémonie est largement retransmise à la télévision.","sources":[{"url":"https://www.royal.uk/wedding-prince-william-and-miss-catherine-middleton?ch=3&page=11","evidence":"Maison royale : vendredi 29 avril 2011, mariage à Westminster.","checked_on":"2026-10-17"}],"level_reason":"Mariage royal contemporain très connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-105","id":"EVT-2904","group":"fun","title":"Grace Kelly épouse religieusement le prince Rainier III de Monaco","start_year":1956,"start_month":4,"start_day":19,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0116","COL-0062","COL-0082"],"description":"L’actrice américaine épouse le prince à la cathédrale de Monaco. Le titre précise la cérémonie religieuse du 19 avril, après le mariage civil de la veille.","sources":[{"url":"https://institut-audiovisuel.mc/medias/au-pied-de-la-cathedrale/","evidence":"Archive audiovisuelle monégasque : jeudi 19 avril 1956, mariage religieux à la cathédrale.","checked_on":"2026-10-17"}],"level_reason":"Union célèbre entre cinéma et monarchie, cérémonie précisément identifiée.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-106","id":"EVT-2905","group":"fun","title":"Fortnite Battle Royale devient gratuit sur ordinateurs et consoles","start_year":2017,"start_month":9,"start_day":26,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0115"],"description":"Le mode oppose cent joueurs dans une partie d’élimination. Son accès gratuit accompagne la diffusion mondiale de Fortnite, distinct du mode coopératif initial du jeu.","sources":[{"url":"https://www.fortnite.com/news/fortnite-battle-royale-goes-free?lang=fr","evidence":"Epic : accès gratuit annoncé pour le 26 septembre 2017 sur PC, Mac, PS4 et Xbox One.","checked_on":"2026-10-17"}],"level_reason":"Jeu très connu ; mode Battle Royale et lancement gratuit précisés.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-107","id":"EVT-2906","group":"fun","title":"Pokémon GO est lancé en Australie, en Nouvelle-Zélande et aux États-Unis","start_year":2016,"start_month":7,"start_day":6,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0115"],"description":"Le jeu sur téléphone fait chercher des Pokémon dans l’environnement réel. Sa diffusion commence dans ces trois pays avant d’être étendue ailleurs.","sources":[{"url":"https://pokemongo.com/news/launch","evidence":"Annonce originale du 6 juillet 2016 : disponible dans les trois territoires nommés.","checked_on":"2026-10-17"}],"level_reason":"Jeu populaire et lancement géographique explicitement limité.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-108","id":"EVT-2907","group":"fun","title":"ABBA remporte l’Eurovision avec Waterloo","start_year":1974,"start_month":4,"start_day":6,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0115","COL-0062","COL-0082"],"description":"Le groupe suédois gagne le concours à Brighton. Cette victoire lance une carrière internationale majeure dans la musique pop.","sources":[{"url":"https://www.rte.ie/archives/2014/0404/606651-abba-win-eurovision/","evidence":"Archives du diffuseur RTÉ : victoire du 6 avril 1974 avec Waterloo.","checked_on":"2026-10-17"}],"level_reason":"Groupe et chanson très connus, distinct de la simple édition du concours.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-109","id":"EVT-2908","group":"fun","title":"Instagram est lancé comme application de partage de photos","start_year":2010,"start_month":10,"start_day":6,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0115"],"description":"Instagram arrive sur iPhone avec ses filtres photographiques.","sources":[{"url":"https://techcrunch.com/2010/10/06/instagram-launch/","evidence":"Annonce de lancement contemporaine, 6 octobre 2010.","checked_on":"2026-10-17"}],"level_reason":"Application familière à un large public.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-110","id":"EVT-2909","group":"histoire","title":"Le Cameroun sous tutelle française devient indépendant","start_year":1960,"start_month":1,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"Le territoire accède à la souveraineté sous le nom de République du Cameroun. Cette étape précède la réunification avec la partie méridionale du Cameroun britannique.","sources":[{"url":"https://mintoul.gov.cm/cameroun-en-decouverte/histoire-du-cameroun/lindependance-la-reunification/","evidence":"Ministère camerounais : indépendance du Cameroun oriental le 1er janvier 1960, réunification distincte en 1961.","checked_on":"2026-10-17"}],"level_reason":"Indépendance majeure d’un pays francophone connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-111","id":"EVT-2910","group":"histoire","title":"La Côte d’Ivoire devient indépendante","start_year":1960,"start_month":8,"start_day":7,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"Le pays quitte la souveraineté française. Félix Houphouët-Boigny dirige le nouvel État dans le contexte des indépendances africaines de 1960.","sources":[{"url":"https://history.state.gov/countries/cote-divoire","evidence":"Archives diplomatiques : fin de la souveraineté française et indépendance le 7 août 1960.","checked_on":"2026-10-17"}],"level_reason":"Pays francophone familier et grande vague de décolonisation.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-112","id":"EVT-2911","group":"histoire","title":"Le Gabon proclame son indépendance","start_year":1960,"start_month":8,"start_day":17,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"Léon M’ba dirige le nouvel État issu de l’Afrique-Équatoriale française. Le Gabon devient souverain dans la grande vague des indépendances africaines.","sources":[{"url":"https://history.state.gov/countries/gabon","evidence":"Office of the Historian : proclamation de l’indépendance le 17 août 1960.","checked_on":"2026-10-17"}],"level_reason":"Indépendance d’un pays francophone connu, située dans la vague de 1960.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-113","id":"EVT-2912","group":"histoire","title":"Le Dahomey, futur Bénin, devient indépendant","start_year":1960,"start_month":8,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"Le Dahomey sort de la souveraineté française. Le pays prendra le nom de Bénin plus tard, sans que ce changement de nom constitue une nouvelle indépendance.","sources":[{"url":"https://history.state.gov/countries/benin","evidence":"Archives diplomatiques : indépendance proclamée le 1er août 1960 ; nom Bénin adopté en 1975.","checked_on":"2026-10-17"}],"level_reason":"Pays francophone identifié par son nom actuel et son ancien nom.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-114","id":"EVT-2913","group":"histoire","title":"Le Togo devient indépendant","start_year":1960,"start_month":4,"start_day":27,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"L’ancien territoire sous tutelle des Nations unies et administration française accède à la souveraineté. Sylvanus Olympio dirige son gouvernement.","sources":[{"url":"https://history.state.gov/countries/togo","evidence":"Archives diplomatiques : indépendance reconnue le 27 avril 1960, fin de la tutelle administrée par la France.","checked_on":"2026-10-17"}],"level_reason":"Indépendance d’un pays francophone connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-115","id":"EVT-2914","group":"histoire","title":"Le Kenya devient indépendant","start_year":1963,"start_month":12,"start_day":12,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082"],"description":"Le drapeau kényan remplace l’Union Jack lors des cérémonies d’indépendance. Jomo Kenyatta devient le premier Premier ministre de l’État souverain.","sources":[{"url":"https://presidentiallibrary.go.ke/presidents/he-mzee-jomo-kenyatta","evidence":"Bibliothèque présidentielle kényane : indépendance le 12 décembre 1963 ; passage à la république en 1964 distinct.","checked_on":"2026-10-17"}],"level_reason":"Pays et dirigeant majeurs de la décolonisation africaine.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-116","id":"EVT-2915","group":"histoire","title":"La Jamaïque devient indépendante du Royaume-Uni","start_year":1962,"start_month":8,"start_day":6,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082"],"description":"Le nouveau drapeau jamaïcain est hissé après plusieurs siècles de domination britannique. L’État demeure membre du Commonwealth.","sources":[{"url":"https://nlj.gov.jm/jamaicaindependence1962/","evidence":"Bibliothèque nationale de Jamaïque : indépendance le 6 août 1962.","checked_on":"2026-10-17"}],"level_reason":"Pays caribéen familier et date nationale claire.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-117","id":"EVT-2916","group":"histoire","title":"La Guinée proclame son indépendance après le non au référendum","start_year":1958,"start_month":10,"start_day":2,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0075","COL-0082","COL-0061"],"description":"Après le rejet du projet de Communauté française au référendum, la Guinée devient indépendante. Sékou Touré dirige le nouvel État.","sources":[{"url":"https://mjp.univ-perp.fr/constit/gn1958.htm","evidence":"Digithèque de l’université de Perpignan : indépendance proclamée le 2 octobre 1958, distincte du vote du 28 septembre.","checked_on":"2026-10-17"}],"level_reason":"Rupture majeure de la décolonisation française et dirigeant connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-118","id":"EVT-2917","group":"histoire","title":"Le Tanganyika devient indépendant avant la formation de la Tanzanie","start_year":1961,"start_month":12,"start_day":9,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0075","COL-0082"],"description":"Julius Nyerere dirige le nouvel État issu d’un territoire sous tutelle britannique. Le Tanganyika s’unira ultérieurement à Zanzibar pour former la Tanzanie.","sources":[{"url":"https://history.state.gov/countries/tanzania","evidence":"Archives diplomatiques : indépendance du Tanganyika le 9 décembre 1961.","checked_on":"2026-10-17"}],"level_reason":"Ancien nom et union ultérieure exigent une distinction historique.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-119","id":"EVT-2918","group":"histoire","title":"La fédération de Malaya devient indépendante","start_year":1957,"start_month":8,"start_day":31,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0075","COL-0082"],"description":"La fédération sort de l’Empire britannique avec Tunku Abdul Rahman à sa tête. Cette indépendance précède la formation de la fédération de Malaysia élargie en 1963.","sources":[{"url":"https://history.state.gov/countries/malaysia","evidence":"Archives diplomatiques : fédération de Malaya indépendante le 31 août 1957 ; élargissement de 1963 distingué.","checked_on":"2026-10-17"}],"level_reason":"Entité de 1957 distinguée de l’État fédéral élargi de 1963.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-120","id":"EVT-2919","group":"histoire","title":"Le Botswana devient indépendant sous son nouveau nom","start_year":1966,"start_month":9,"start_day":30,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0075","COL-0082"],"description":"L’ancien protectorat britannique du Bechuanaland accède à la souveraineté. Le nouvel État prend le nom de Botswana.","sources":[{"url":"https://history.state.gov/countries/botswana","evidence":"Archives diplomatiques : indépendance du Botswana le 30 septembre 1966, ancien Bechuanaland.","checked_on":"2026-10-17"}],"level_reason":"Ancien protectorat moins familier, niveau intermédiaire.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-121","id":"EVT-2920","group":"histoire","title":"La Barbade devient indépendante","start_year":1966,"start_month":11,"start_day":30,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0075","COL-0082"],"description":"L’île caribéenne devient un État souverain au sein du Commonwealth après une conférence constitutionnelle avec le Royaume-Uni.","sources":[{"url":"https://history.state.gov/countries/barbados","evidence":"Archives diplomatiques : État indépendant le 30 novembre 1966.","checked_on":"2026-10-17"}],"level_reason":"Indépendance caribéenne moins connue que celle de la Jamaïque.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-122","id":"EVT-2921","group":"histoire","title":"Le manifeste de Morges lance le projet du WWF","start_year":1961,"start_month":4,"start_day":29,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0076","COL-0062","COL-0082"],"description":"Des défenseurs de la nature proposent un fonds international pour financer la conservation. Ce manifeste est à l’origine du WWF, connu pour son emblème au panda.","sources":[{"url":"https://wwflac.awsassets.panda.org/downloads/enaccion_12_ing_8_web.pdf","evidence":"Publication WWF : manifeste établi le 29 avril 1961 en Suisse, distinct de l’ouverture ultérieure du bureau.","checked_on":"2026-10-17"}],"level_reason":"Organisation au panda très connue ; acte fondateur explicitement nommé.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-123","id":"EVT-2922","group":"histoire","title":"L’Union internationale pour la protection de la nature est fondée à Fontainebleau","start_year":1948,"start_month":10,"start_day":5,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0076","COL-0061","COL-0062","COL-0082"],"description":"Des gouvernements et des organisations se rassemblent pour protéger la nature. L’institution prendra ensuite le nom d’Union internationale pour la conservation de la nature, ou UICN.","sources":[{"url":"https://iucn.org/about-iucn/history","evidence":"UICN : fondation à Fontainebleau le 5 octobre 1948.","checked_on":"2026-10-17"}],"level_reason":"Institution de conservation importante mais moins familière que le WWF.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-124","id":"EVT-2923","group":"histoire","title":"L’Amoco Cadiz s’échoue et provoque une marée noire en Bretagne","start_year":1978,"start_month":3,"start_day":16,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0076","COL-0061","COL-0062","COL-0082"],"description":"Après une panne de gouvernail, le pétrolier s’échoue près de Portsall. Le pétrole se répand sur une grande partie du littoral breton.","sources":[{"url":"https://www.itopf.org/in-action/case-studies/amoco-cadiz-france-1978/","evidence":"ITOPF, intervenu sur place : échouement le 16 mars 1978.","checked_on":"2026-10-17"}],"level_reason":"Catastrophe environnementale majeure et connue en France.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-125","id":"EVT-2924","group":"histoire","title":"L’Exxon Valdez provoque une marée noire en Alaska","start_year":1989,"start_month":3,"start_day":24,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0076","COL-0082"],"description":"Le pétrolier s’échoue dans le détroit du Prince-William. La pollution touche durablement les côtes et les écosystèmes marins d’Alaska.","sources":[{"url":"https://darrp.noaa.gov/oil-spills/exxon-valdez","evidence":"NOAA : échouement et déversement de pétrole le 24 mars 1989.","checked_on":"2026-10-17"}],"level_reason":"Marée noire mondialement connue.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-126","id":"EVT-2925","group":"histoire","title":"Le naufrage de l’Erika provoque une marée noire sur les côtes françaises","start_year":1999,"start_month":12,"start_day":12,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0076","COL-0061","COL-0062","COL-0082"],"description":"Le pétrolier se brise au large de la Bretagne. Le fioul transporté souille une partie du littoral atlantique français.","sources":[{"url":"https://documentservices.iopcfunds.org/wp-content/themes/iopcfunds/scripts/download-document.php?doc=19342&lang=en&name=IOPC-MAR11-3-3","evidence":"Fonds internationaux d’indemnisation : accident Erika daté du 12 décembre 1999, rupture et naufrage.","checked_on":"2026-10-17"}],"level_reason":"Catastrophe française très connue, traitée sobrement.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-127","id":"EVT-2926","group":"histoire","title":"La convention de Vienne organise la coopération pour protéger la couche d’ozone","start_year":1985,"start_month":3,"start_day":22,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0076","COL-0062","COL-0082"],"description":"Les États adoptent un cadre de recherche et de coopération face à l’appauvrissement de l’ozone. Les restrictions chiffrées sur certaines substances seront précisées par le protocole de Montréal.","sources":[{"url":"https://ozone.unep.org/system/files/documents/1985-03-22_Vienna-Convention_Final-Act.E.pdf","evidence":"Acte final de la conférence : adoption le 22 mars 1985.","checked_on":"2026-10-17"}],"level_reason":"Convention moins connue, clairement distinguée du protocole de Montréal déjà présent.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-128","id":"EVT-2927","group":"histoire","title":"La convention sur la diversité biologique est adoptée à Nairobi","start_year":1992,"start_month":5,"start_day":22,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0076","COL-0082"],"description":"Le texte vise la conservation de la biodiversité, son utilisation durable et le partage des bénéfices des ressources génétiques. Son adoption précède l’ouverture à la signature au sommet de Rio.","sources":[{"url":"https://www.cbd.int/doc/legal/cbd-en.pdf","evidence":"Texte publié par le secrétariat : adoption initiale le 22 mai 1992.","checked_on":"2026-10-17"}],"level_reason":"Accord mondial sur un enjeu familier ; adoption distinguée de la signature à Rio.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-129","id":"EVT-2928","group":"histoire","title":"La convention de Stockholm cible les polluants organiques persistants","start_year":2001,"start_month":5,"start_day":22,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0076","COL-0062"],"description":"L’accord prévoit de réduire ou d’éliminer des substances toxiques qui persistent dans l’environnement et s’accumulent dans les organismes.","sources":[{"url":"https://www.pops.int/TheConvention/Overview","evidence":"Secrétariat : convention adoptée à Stockholm le 22 mai 2001.","checked_on":"2026-10-17"}],"level_reason":"Traité spécialisé, niveau intermédiaire et contenu expliqué simplement.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-130","id":"EVT-2929","group":"histoire","title":"La convention de Minamata sur le mercure est adoptée","start_year":2013,"start_month":10,"start_day":10,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0076"],"description":"Adopté au Japon, l’accord vise à limiter l’utilisation et les rejets de mercure. Son nom rappelle la pollution qui a gravement touché la ville de Minamata.","sources":[{"url":"https://www.unep.org/globalmercurypartnership/resources/policy-and-strategy/minamata-convention-mercury","evidence":"PNUE : adoption le 10 octobre 2013 à Kumamoto, entrée en vigueur ultérieure en 2017.","checked_on":"2026-10-17"}],"level_reason":"Accord environnemental spécialisé, traité sans banaliser les victimes.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-131","id":"EVT-2930","group":"histoire","title":"Theodore Maiman fait fonctionner le premier laser","start_year":1960,"start_month":5,"start_day":16,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0071","COL-0112","COL-0113","COL-0082"],"description":"Maiman obtient une impulsion de lumière cohérente avec un cristal de rubis. Le laser deviendra un outil de recherche et de nombreuses technologies quotidiennes.","sources":[{"url":"https://www.aps.org/apsnews/2010/05/physics-history","evidence":"American Physical Society : premier laser fonctionnel le 16 mai 1960.","checked_on":"2026-10-17"}],"level_reason":"Invention majeure au nom familier.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-132","id":"EVT-2931","group":"histoire","title":"Alec Jeffreys découvre le principe de l’empreinte génétique","start_year":1984,"start_month":9,"start_day":10,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0071","COL-0062","COL-0082"],"description":"À Leicester, Jeffreys observe des motifs d’ADN permettant de distinguer des personnes. Sa découverte ouvrira de nouveaux usages en identification et en médecine légale.","sources":[{"url":"https://le.ac.uk/dna-fingerprinting/hotspots-and-minisatellites","evidence":"Université de Leicester : découverte le lundi 10 septembre 1984.","checked_on":"2026-10-17"}],"level_reason":"Technique connue, mais chercheur et étape expérimentale plus spécialisés.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-133","id":"EVT-2932","group":"histoire","title":"La découverte de l’exoplanète 51 Pegasi b est annoncée","start_year":1995,"start_month":10,"start_day":6,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0071","COL-0070","COL-0061","COL-0062","COL-0112","COL-0082"],"description":"Michel Mayor et Didier Queloz annoncent une planète en orbite autour d’une étoile semblable au Soleil. Ce résultat concerne une étoile de type solaire, et non les premières planètes déjà détectées autour d’un pulsar.","sources":[{"url":"https://www.hq.eso.org/public/announcements/ann19049/","evidence":"ESO : découverte annoncée le 6 octobre 1995 avec le spectrographe ELODIE en Haute-Provence.","checked_on":"2026-10-17"}],"level_reason":"Découverte majeure de planète extrasolaire, périmètre de la première précisé.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-134","id":"EVT-2933","group":"histoire","title":"James Chadwick publie l’annonce du neutron","start_year":1932,"start_month":2,"start_day":27,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0071","COL-0062","COL-0082"],"description":"Dans une lettre à Nature, Chadwick propose qu’un rayonnement observé provienne de particules sans charge électrique. Le neutron devient un élément central de la description du noyau atomique.","sources":[{"url":"https://www.nature.com/articles/129312a0","evidence":"Article original Possible Existence of a Neutron, Nature 129, p. 312, numéro du 27 février 1932.","checked_on":"2026-10-17"}],"level_reason":"Constituant de l’atome connu mais publication scientifique précise.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-135","id":"EVT-2934","group":"histoire","title":"Stanley Miller publie la synthèse d’acides aminés dans une expérience sur la Terre primitive","start_year":1953,"start_month":5,"start_day":15,"precision":"DAY","date_status":"EXACT","niveau":3,"packs":["COL-0071","COL-0082"],"description":"Miller soumet un mélange de gaz et de vapeur d’eau à des décharges électriques. Il obtient des acides aminés, sans avoir créé de la vie ni démontré la composition exacte de l’atmosphère primitive.","sources":[{"url":"https://www.science.org/doi/10.1126/science.117.3046.528","evidence":"Référence originale : Science 117, 528-529, 15 mai 1953 ; date et résumé vérifiés dans la notice OpenAIRE, le site éditeur refusant la consultation automatisée.","checked_on":"2026-10-17"},{"url":"https://explore.openaire.eu/search/publication?pid=10.1126%2Fscience.117.3046.528","evidence":"Notice de publication : 15 May 1953, Science, vol. 117, p. 528-529.","checked_on":"2026-10-17"}],"level_reason":"Expérience de chimie prébiotique spécialisée, limites explicitement formulées.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-136","id":"EVT-2935","group":"histoire","title":"Marie Curie donne son premier cours comme professeure à la Sorbonne","start_year":1906,"start_month":11,"start_day":5,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0071","COL-0112","COL-0073","COL-0061","COL-0062","COL-0082"],"description":"Marie Curie devient la première femme à enseigner comme professeure à la Sorbonne. Elle reprend la chaire de physique laissée vacante après la mort de Pierre Curie.","sources":[{"url":"https://www.sorbonne.fr/pose-dune-plaque-commemorative-en-souvenir-de-marie-curie/","evidence":"Chancellerie des universités : premier cours le 5 novembre 1906, première femme professeure à la Sorbonne.","checked_on":"2026-10-17"}],"level_reason":"Scientifique très connue et première féminine claire.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-137","id":"EVT-2936","group":"histoire","title":"Ada Lovelace publie ses notes sur la machine analytique de Babbage","start_year":1843,"start_month":null,"start_day":null,"precision":"YEAR","date_status":"EXACT","niveau":1,"packs":["COL-0071","COL-0062","COL-0081"],"description":"Lovelace traduit un texte de Menabrea et l’enrichit de notes sur les possibilités de la machine. Elle y décrit notamment une méthode de calcul des nombres de Bernoulli.","sources":[{"url":"https://collection.sciencemuseumgroup.org.uk/objects/co8652385/book-sketch-of-the-analytical-engine-invented-by-charles-babbage-esq","evidence":"Exemplaire original conservé au Science Museum : édition de Londres 1843. Aucun jour ajouté.","checked_on":"2026-10-17"}],"level_reason":"Pionnière de l’informatique connue ; titre évitant la revendication discutée de toute première programmeuse.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-138","id":"EVT-2937","group":"histoire","title":"Cassini devient la première sonde en orbite autour de Saturne","start_year":2004,"start_month":7,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0070","COL-0071","COL-0112"],"description":"Après un long trajet, Cassini freine pour être capturée par la gravité de Saturne. Elle commence une étude prolongée de la planète, de ses anneaux et de ses lunes.","sources":[{"url":"https://science.nasa.gov/mission/cassini/faq/","evidence":"NASA : arrivée le 1er juillet 2004 en temps universel, encore le 30 juin dans les fuseaux américains.","checked_on":"2026-10-17"}],"level_reason":"Planète familière et première exploration orbitale clairement définie.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-139","id":"EVT-2938","group":"histoire","title":"Voyager 2 réalise le premier survol rapproché de Neptune","start_year":1989,"start_month":8,"start_day":25,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0070","COL-0071","COL-0112","COL-0082"],"description":"La sonde observe Neptune et sa grande lune Triton. Ce passage conclut sa visite rapprochée des quatre planètes géantes du Système solaire.","sources":[{"url":"https://science.nasa.gov/mission/voyager/voyager-2/","evidence":"NASA : rencontre avec Neptune le 25 août 1989 à 03:56 UT.","checked_on":"2026-10-17"}],"level_reason":"Planète connue et première rencontre spatiale identifiable.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-140","id":"EVT-2939","group":"histoire","title":"Chang’e 4 réussit le premier alunissage en douceur sur la face cachée","start_year":2019,"start_month":1,"start_day":3,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0070","COL-0071","COL-0112"],"description":"La mission chinoise se pose dans le cratère Von Kármán. Un satellite relais permet les communications avec la Terre, invisible depuis ce côté de la Lune.","sources":[{"url":"https://www.cnsa.gov.cn/english/n6465652/n6465653/c6805049/content.html","evidence":"Agence spatiale chinoise : premier alunissage sur la face cachée, 3 janvier 2019.","checked_on":"2026-10-17"}],"level_reason":"Première spatiale majeure, lieu clairement distingué des alunissages antérieurs.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-141","id":"EVT-2940","group":"histoire","title":"Le rover Perseverance se pose sur Mars","start_year":2021,"start_month":2,"start_day":18,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0070","COL-0071"],"description":"Le robot américain atteint le cratère Jezero. Il recherche notamment des traces d’environnements anciens favorables à la vie et prépare des échantillons pour de futures études.","sources":[{"url":"https://www.nasa.gov/news-release/touchdown-nasas-mars-perseverance-rover-safely-lands-on-red-planet/","evidence":"Communiqué original NASA : atterrissage le 18 février 2021.","checked_on":"2026-10-17"}],"level_reason":"Mission martienne récente et largement diffusée.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-142","id":"EVT-2941","group":"histoire","title":"Le traité de Lisbonne entre en vigueur","start_year":2009,"start_month":12,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0074","COL-0062"],"description":"Le traité réforme les institutions de l’Union européenne et donne un statut juridique renforcé à la Charte des droits fondamentaux. Cette entrée en vigueur est distincte de la signature de 2007.","sources":[{"url":"https://www.consilium.europa.eu/cs/lisbon-treaty/","evidence":"Conseil de l’Union : entrée en vigueur le 1er décembre 2009.","checked_on":"2026-10-17"}],"level_reason":"Grand traité européen et changement institutionnel connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-143","id":"EVT-2942","group":"histoire","title":"Le traité de Nice est signé","start_year":2001,"start_month":2,"start_day":26,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0074","COL-0062","COL-0061"],"description":"Les États membres modifient les règles institutionnelles de l’Union européenne pour préparer son élargissement. La signature précède l’entrée en vigueur du traité.","sources":[{"url":"https://www.consilium.europa.eu/en/documents/treaties-agreements/agreement/?id=2001010","evidence":"Registre du Conseil : signature à Nice le 26 février 2001.","checked_on":"2026-10-17"}],"level_reason":"Traité moins connu que Maastricht ou Lisbonne.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-144","id":"EVT-2943","group":"histoire","title":"La Croatie rejoint l’Union européenne","start_year":2013,"start_month":7,"start_day":1,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0074","COL-0062"],"description":"La Croatie devient le vingt-huitième État membre au moment de son adhésion. Cette étape suit un processus de négociation et de ratification.","sources":[{"url":"https://www.ecb.europa.eu/press/pr/date/2013/html/pr130701.en.html","evidence":"Communiqué original BCE du 1er juillet 2013 : adhésion effective ce jour.","checked_on":"2026-10-17"}],"level_reason":"Adhésion récente d’un pays européen connu.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-145","id":"EVT-2944","group":"histoire","title":"Les premières élections européennes au suffrage direct commencent","start_year":1979,"start_month":6,"start_day":7,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0074","COL-0062","COL-0073","COL-0082"],"description":"Les citoyens élisent directement les députés européens pour la première fois. Le scrutin se déroule du 7 au 10 juin selon les pays ; la date retenue est celle de son début.","sources":[{"url":"https://www.europarl.europa.eu/topics/en/article/20240516STO21528/european-elections-highlights-from-the-past","evidence":"Parlement européen : premières élections directes du 7 au 10 juin 1979 ; début explicitement daté.","checked_on":"2026-10-17"}],"level_reason":"Première démocratique connue ; aucune réduction trompeuse du scrutin à un jour unique.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-146","id":"EVT-2945","group":"histoire","title":"La Charte des droits fondamentaux de l’Union européenne est proclamée","start_year":2000,"start_month":12,"start_day":7,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0074","COL-0062","COL-0061","COL-0073"],"description":"Les présidents du Parlement européen, du Conseil et de la Commission proclament la Charte à Nice. Le texte réunit les droits civils, politiques, économiques et sociaux.","sources":[{"url":"https://op.europa.eu/en/publication-detail/-/publication/f6473b0b-05a4-4f41-a6c5-d5a22af773fb/language-en","evidence":"Office des publications : signature et proclamation le 7 décembre 2000 à Nice.","checked_on":"2026-10-17"}],"level_reason":"Texte institutionnel exigeant de distinguer proclamation et portée juridique ultérieure.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-147","id":"EVT-2946","group":"histoire","title":"Jean-Paul II est élu pape","start_year":1978,"start_month":10,"start_day":16,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0072","COL-0062","COL-0082"],"description":"Le cardinal polonais Karol Wojtyła prend le nom de Jean-Paul II. Il devient le premier pape polonais de l’histoire.","sources":[{"url":"https://www.vatican.va/special/canonizzazione-27042014/documents/biografia_gpii_canonizzazione_en.html","evidence":"Biographie officielle : élection le 16 octobre 1978, inauguration du ministère le 22 distincte.","checked_on":"2026-10-17"}],"level_reason":"Pape et première nationale très connus.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-148","id":"EVT-2947","group":"histoire","title":"Le dalaï-lama reçoit le prix Nobel de la paix à Oslo","start_year":1989,"start_month":12,"start_day":10,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0072","COL-0073","COL-0062","COL-0082"],"description":"Le chef spirituel tibétain reçoit la récompense pour son engagement non violent. La date retenue est celle de la remise du prix, et non celle de l’annonce du lauréat.","sources":[{"url":"https://www.dalailama.com/messages/acceptance-speeches/nobel-peace-prize/nobel-peace-prize","evidence":"Discours original d’acceptation à la remise du prix, 10 décembre 1989.","checked_on":"2026-10-17"}],"level_reason":"Personnalité et prix connus, cérémonie explicitement datée.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-149","id":"EVT-2948","group":"histoire","title":"Le pape et le grand imam d’Al-Azhar signent un texte sur la fraternité humaine","start_year":2019,"start_month":2,"start_day":4,"precision":"DAY","date_status":"EXACT","niveau":2,"packs":["COL-0072","COL-0073"],"description":"À Abou Dhabi, François et Ahmed el-Tayeb appellent au dialogue, à la paix et à la coexistence. Le document engage leurs institutions à promouvoir ces principes.","sources":[{"url":"https://www.vatican.va/content/francesco/en/travels/2019/outside/documents/papa-francesco_20190204_documento-fratellanza-umana.html","evidence":"Document original signé à Abou Dhabi le 4 février 2019.","checked_on":"2026-10-17"}],"level_reason":"Étape contemporaine du dialogue interreligieux moins connue, niveau intermédiaire.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-150","id":"EVT-2949","group":"histoire","title":"Napoléon revient aux Tuileries pendant les Cent-Jours","start_year":1815,"start_month":3,"start_day":20,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0067","COL-0061","COL-0062","COL-0081"],"description":"Après son débarquement à Golfe-Juan et sa remontée vers Paris, Napoléon retrouve le palais des Tuileries. Louis XVIII a quitté la capitale.","sources":[{"url":"https://www.napoleon.org/histoire-des-2-empires/articles/delbe-a-waterloo-un-autre-regard-sur-la-periode-1814-1815","evidence":"Fondation Napoléon : arrivée à Paris le 20 mars au soir ; distincte du débarquement du 1er mars déjà présent.","checked_on":"2026-10-17"}],"level_reason":"Retour au pouvoir de Napoléon, étape célèbre des Cent-Jours.","aliases":[],"territory":"sans objet","kind":"event"},{"proposal_id":"M2-151","id":"EVT-2950","group":"sport","title":"Alain Bernard devient champion olympique du 100 mètres nage libre","start_year":2008,"start_month":8,"start_day":14,"precision":"DAY","date_status":"EXACT","niveau":1,"packs":["COL-0105","COL-0108","COL-0061"],"description":"Le nageur français remporte la finale à Pékin. Ce succès l’installe parmi les grandes figures de la natation française.","sources":[{"url":"https://www.worldaquatics.com/athletes/1011351/alain-bernard/medals","evidence":"World Aquatics : or olympique du 100 m nage libre, Beijing, Aug 14 2008.","checked_on":"2026-10-17"}],"level_reason":"Victoire française célèbre dans l’épreuve reine du sprint en natation.","aliases":[],"territory":"sans objet","kind":"event"}],"associations":[{"event_id":"EVT-2340","pack_id":"COL-0113","reason":"Le Walkman complète les inventions du quotidien, sans changement de difficulté.","snapshot":{"id":"EVT-2340","title":"Sony commercialise le premier Walkman au Japon","titre_question":null,"niveau":1,"precision":"DAY","playable":true,"playable_mode":"DAY","date_status":"EXACT","start_year":1979,"start_month":7,"start_day":1,"end_year":null,"end_month":null,"end_day":null,"description":"Le baladeur à cassette permet d’emporter sa musique avec un casque léger. Sony développe un nouvel usage individuel de l’écoute."}},{"event_id":"EVT-0990","pack_id":"COL-0113","reason":"La présentation du premier iPhone complète les inventions familières.","snapshot":{"id":"EVT-0990","title":"Présentation du premier iPhone par Steve Jobs","titre_question":null,"niveau":1,"precision":"DAY","playable":true,"playable_mode":"DAY","date_status":"EXACT","start_year":2007,"start_month":1,"start_day":9,"end_year":null,"end_month":null,"end_day":null,"description":"Présentation du premier iPhone par Steve Jobs. Repère daté de 9 janvier 2007, lié à Économie et Techniques et technologies, avec un ancrage principal en Monde / global et États-Unis."}},{"event_id":"EVT-2016","pack_id":"COL-0116","reason":"Le couronnement déjà présent complète le pack royal, en conservant le niveau Intermédiaire.","snapshot":{"id":"EVT-2016","title":"Couronnement de Charles III","titre_question":null,"niveau":2,"precision":"DAY","playable":true,"playable_mode":"DAY","date_status":"EXACT","start_year":2023,"start_month":5,"start_day":6,"end_year":null,"end_month":null,"end_day":null,"description":"Couronnement de Charles III. Repère de culture générale repris du lot de candidats V15."}}],"packs":[{"id":"COL-0061","slug":"france","parent_id":null,"active":true},{"id":"COL-0062","slug":"europe","parent_id":null,"active":true},{"id":"COL-0067","slug":"epoque-napoleonienne","parent_id":null,"active":true},{"id":"COL-0070","slug":"espace","parent_id":null,"active":true},{"id":"COL-0071","slug":"sciences","parent_id":null,"active":true},{"id":"COL-0072","slug":"religions","parent_id":null,"active":true},{"id":"COL-0073","slug":"droits-libertes","parent_id":null,"active":true},{"id":"COL-0074","slug":"construction-europeenne","parent_id":null,"active":true},{"id":"COL-0075","slug":"decolonisation","parent_id":null,"active":true},{"id":"COL-0076","slug":"environnement","parent_id":null,"active":true},{"id":"COL-0081","slug":"xixe-siecle","parent_id":null,"active":true},{"id":"COL-0082","slug":"xxe-siecle","parent_id":null,"active":true},{"id":"COL-0105","slug":"sport","parent_id":null,"active":true},{"id":"COL-0106","slug":"sport-football","parent_id":"COL-0105","active":true},{"id":"COL-0107","slug":"sport-tennis","parent_id":"COL-0105","active":true},{"id":"COL-0108","slug":"sport-jeux-olympiques","parent_id":"COL-0105","active":true},{"id":"COL-0109","slug":"sport-cyclisme","parent_id":"COL-0105","active":true},{"id":"COL-0110","slug":"sport-mecanique","parent_id":"COL-0105","active":true},{"id":"COL-0111","slug":"sport-autres-exploits","parent_id":"COL-0105","active":true},{"id":"COL-0112","slug":"fun-grandes-premieres","parent_id":null,"active":true},{"id":"COL-0113","slug":"fun-inventions-improbables","parent_id":null,"active":true},{"id":"COL-0114","slug":"fun-films-cultes","parent_id":null,"active":true},{"id":"COL-0115","slug":"fun-pop-culture","parent_id":null,"active":true},{"id":"COL-0116","slug":"fun-rois-scandales-trahisons","parent_id":null,"active":true},{"id":"COL-0117","slug":"fun-histoire-derape","parent_id":null,"active":true}]}'::jsonb;
  ev jsonb;
begin
  if exists(select 1 from histoire.migrations_appliquees where version='20261017172349') then return; end if;
  if not exists(select 1 from histoire.events) then
    raise notice 'Massif2 différé : importer le corpus local puis rejouer la migration'; return;
  end if;
  if not exists(select 1 from histoire.migrations_appliquees where version='20261015120156')
    or not exists(select 1 from histoire.migrations_appliquees where version='20261015201336')
    or not exists(select 1 from histoire.migrations_appliquees where version='20261016124921') then
    raise exception 'Massif2 : packs fun #91 et administration #120 requis';
  end if;
  if exists(select 1 from jsonb_array_elements(contenu->'packs') x left join histoire.packs p on p.id=x->>'id'
    where p.id is null or not p.active or p.slug is distinct from x->>'slug' or p.parent_id is distinct from x->>'parent_id') then
    raise exception 'Massif2 : pack cible absent ou modifié ; refaire audit et relecture';
  end if;
  if exists(select 1 from jsonb_array_elements(contenu->'events') x join histoire.events e on e.id=x->>'id') then
    raise exception 'Massif2 : identifiant événement déjà occupé ; aucun remplacement autorisé';
  end if;
  -- Même normalisation que #120, seuil conservateur 0,6 pour une même date.
  -- Une nouvelle création ou un quasi-doublon impose une relecture ; jamais d’écrasement.
  if exists(select 1 from jsonb_array_elements(contenu->'events') x cross join histoire.events e
    left join histoire.event_answers a on a.event_id=e.id
    where histoire.normalize_answer(e.title)=histoire.normalize_answer(x->>'title')
      or (row(a.start_year,a.start_month,a.start_day,a.end_year,a.end_month,a.end_day)
        is not distinct from row((x->>'start_year')::integer,(x->>'start_month')::smallint,(x->>'start_day')::smallint,
          null::integer,null::smallint,null::smallint)
        and extensions.similarity(histoire.normalize_answer(e.title),histoire.normalize_answer(x->>'title'))>=0.6)) then
    raise exception 'Massif2 : doublon ou proximité à relire ; refaire audit et relecture';
  end if;
  if exists(select 1 from jsonb_array_elements(contenu->'associations') x left join histoire.events e on e.id=x->>'event_id' where e.id is null) then
    raise exception 'Massif2 : événement à réutiliser absent';
  end if;
  -- Les modifications éditoriales antérieures ne sont jamais remplacées :
  -- une dérive depuis le dossier relu exige un nouvel audit avant insertion.
  if exists(select 1 from jsonb_array_elements(contenu->'associations') x
    join histoire.events e on e.id=x->>'event_id'
    left join histoire.event_answers a on a.event_id=e.id
    where jsonb_build_object(
      'id',e.id,'title',e.title,'titre_question',e.titre_question,'niveau',e.niveau,
      'precision',e.precision,'playable',e.playable,'playable_mode',e.playable_mode,
      'date_status',e.date_status,'start_year',a.start_year,'start_month',a.start_month,'start_day',a.start_day,
      'end_year',a.end_year,'end_month',a.end_month,'end_day',a.end_day,'description',a.description)
      is distinct from ((x->'snapshot')-'packs'-'topics')) then
    raise exception 'Massif2 : événement, date ou correction modifié depuis le relevé ; refaire audit et relecture';
  end if;
  for ev in select x from jsonb_array_elements(contenu->'events') x loop
    insert into histoire.events(id,title,titre_question,event_type,precision,date_status,playable,playable_mode,importance,difficulty,niveau,source_status)
      values(ev->>'id',ev->>'title',null,'POINT',ev->>'precision',ev->>'date_status',true,ev->>'precision',3,
        case (ev->>'niveau')::integer when 1 then 2 when 2 then 3 else 5 end,(ev->>'niveau')::smallint,'SUPPORTED_B');
    insert into histoire.event_answers(event_id,start_year,start_month,start_day,date_text,description,notes)
      values(ev->>'id',(ev->>'start_year')::integer,(ev->>'start_month')::smallint,(ev->>'start_day')::smallint,
        concat(ev->>'start_year',case when ev->>'start_month' is not null then '-'||lpad(ev->>'start_month',2,'0') else '' end,
          case when ev->>'start_day' is not null then '-'||lpad(ev->>'start_day',2,'0') else '' end),ev->>'description',
        'Sources V1.2 Massif2 #122 : '||(ev->'sources')::text||' ; territoire : '||coalesce(ev->>'territory','sans objet')||' ; niveau : '||(ev->>'level_reason'));
    insert into histoire.event_aliases(event_id,alias)
      select ev->>'id',alias from (select ev->>'title' alias union select jsonb_array_elements_text(ev->'aliases')) a;
  end loop;
  -- Ajouter en fin de pack sans déplacer une association antérieure.
  with liens as (
    select e->>'id' event_id,p.pack_id,ordinalite from jsonb_array_elements(contenu->'events') with ordinality v(e,ordinalite)
      cross join lateral jsonb_array_elements_text(e->'packs') p(pack_id)
  )
  insert into histoire.pack_events(pack_id,event_id,position)
    select pack_id,event_id,((select coalesce(max(pe.position),0) from histoire.pack_events pe where pe.pack_id=l.pack_id)
      +row_number() over(partition by pack_id order by ordinalite))::integer from liens l;
  -- Le v18 préserve ces liens vers les packs existants via le mécanisme #120.
  insert into histoire.admin_pack_additions(pack_id,event_id)
    select p.pack_id,e->>'id' from jsonb_array_elements(contenu->'events') e
      cross join lateral jsonb_array_elements_text(e->'packs') p(pack_id);
  -- Réemplois A0 : ajouts seulement, jamais réécriture d’un événement existant.
  with manquants as (
    select x->>'pack_id' pack_id,x->>'event_id' event_id,
      row_number() over(partition by x->>'pack_id' order by ordinalite) rang
    from jsonb_array_elements(contenu->'associations') with ordinality a(x,ordinalite)
    where not exists(select 1 from histoire.pack_events pe where pe.pack_id=x->>'pack_id' and pe.event_id=x->>'event_id')
  )
  insert into histoire.pack_events(pack_id,event_id,position)
    select m.pack_id,m.event_id,((select coalesce(max(pe.position),0) from histoire.pack_events pe where pe.pack_id=m.pack_id)+m.rang)::integer
    from manquants m on conflict(pack_id,event_id) do nothing;
  insert into histoire.admin_pack_additions(pack_id,event_id)
    select x->>'pack_id',x->>'event_id' from jsonb_array_elements(contenu->'associations') x on conflict(pack_id,event_id) do nothing;
  insert into histoire.migrations_appliquees(version,nom) values('20261017172349','enrichissement_v12_massif2');
end $massif2$;$sql_massif2$; end $test_massif2$;
